		return [origin?"【原任务 "+relay.taskKey+" · 原消息 "+origin.messageId+"】\n"+origin.text:"",relay?.consensus?"【当前共同确认版本】\n"+JSON.stringify(relay.consensus):"",pending.length?"【未完成交接】\n"+JSON.stringify(pending.map(h=>({id:h.id,to:h.toBotId,state:h.state,texts:h.texts,files:h.files}))):""].filter(Boolean).join("\n\n");
