				this.patchRoom(room.id, (current) => ({ ...current, mentionSequences: (current.mentionSequences ?? []).map((row) => row.id === finished.id ? finished : row) }));
				this.recordNotice(room.id, "连续接力已完成全部 " + sequence.steps.length + " 步（" + sequence.taskKey + "）。");
